SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS=0;

-- Table: roles
CREATE TABLE IF NOT EXISTS roles (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    doc_id VARCHAR(255) UNIQUE,
    uid CHAR(36) NOT NULL UNIQUE,
    name VARCHAR(255) UNIQUE NOT NULL,
    code VARCHAR(255) UNIQUE NOT NULL,
    description LONGTEXT,
    permissions JSON,
    raw_data JSON,
    created_at DATETIME(3) DEFAULT NOW(),
    updated_at DATETIME(3) DEFAULT NOW()
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: users
CREATE TABLE IF NOT EXISTS users (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    doc_id VARCHAR(255) UNIQUE,
    uid CHAR(36) NOT NULL UNIQUE,
    email VARCHAR(255) UNIQUE NOT NULL,
    name LONGTEXT,
    role_id BIGINT NULL,
    status TINYINT(1) DEFAULT TRUE,
    department LONGTEXT,
    phone LONGTEXT,
    avatar_url LONGTEXT,
    raw_data JSON,
    created_at DATETIME(3) DEFAULT NOW(),
    updated_at DATETIME(3) DEFAULT NOW(),
    CONSTRAINT fk_users_role_id FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

-- Table: employees
CREATE TABLE IF NOT EXISTS employees (
    id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY,
    doc_id VARCHAR(255) UNIQUE,
    uid CHAR(36) NOT NULL UNIQUE,
    user_id BIGINT NULL,
    role_id BIGINT NULL,
    name LONGTEXT,
    first_name LONGTEXT,
    last_name LONGTEXT,
    email VARCHAR(255) UNIQUE,
    phone LONGTEXT,
    department LONGTEXT,
    position LONGTEXT,
    role_type LONGTEXT DEFAULT 'Employé',
    status TINYINT(1) DEFAULT TRUE,
    hire_date DATE,
    salary DECIMAL(18,4) DEFAULT 0,
    photo_url LONGTEXT,
    emergency_contact LONGTEXT,
    work_location LONGTEXT DEFAULT 'Douala',
    badge_code LONGTEXT,
    raw_data JSON,
    created_at DATETIME(3) DEFAULT NOW(),
    updated_at DATETIME(3) DEFAULT NOW(),
    CONSTRAINT fk_employees_user_id FOREIGN KEY (user_id) REFERENCES users(id) ON DELETE SET NULL,
    CONSTRAINT fk_employees_role_id FOREIGN KEY (role_id) REFERENCES roles(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

