    raw_data JSON,
    created_at DATETIME(3) DEFAULT NOW(),
    updated_at DATETIME(3) DEFAULT NOW(),
    CONSTRAINT fk_tasks_employee_id FOREIGN KEY (employee_id) REFERENCES employees(id) ON DELETE SET NULL,
    CONSTRAINT fk_tasks_project_id FOREIGN KEY (project_id) REFERENCES task_projects(id) ON DELETE SET NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

